-- PT118-S3-Q8. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT118-S3-Q8$batch09$ AND q.stimulus=$batch09$Figorian Wildlife Commission: The development of wetlands in industrialized nations for residential and commercial uses has endangered many species. To protect wildlife we must regulate such development in Figoria: future wetland development must be offset by the construction of replacement wetland habitats. Thus, development would cause no net reduction of wetlands and pose no threat to the species that inhabit them.Figorian Development Commission: Other nations have flagrantly developed wetlands at the expense of wildlife. We have conserved. Since Figorian wetland development might not affect wildlife and is necessary for growth, we should allow development. We have as much right to govern our own resources as countries that have already put their natural resources to commercial use.$batch09$ AND q.prompt=$batch09$Which one of the following principles, if accepted, would most strongly support the Figorian Development Commission's position against the Figorian Wildlife Commission's position?$batch09$ AND q.correct_choice=$batch09$C$batch09$) THEN RAISE EXCEPTION 'Question changed: PT118-S3-Q8'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch09$22045154-79ec-4a5a-a196-5b1030ef9c60$batch09$) <> 6 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch09$22045154-79ec-4a5a-a196-5b1030ef9c60$batch09$) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT118-S3-Q8'; END IF; END $guard$;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$The Development Commission insists Figoria has the right to govern its own resources. Handing regulation to an international agreement takes that right away. A works against the commission it is supposed to help.$batch09$), ($batch09$B$batch09$, $batch09$If future generations' right to wildlife outranks a nation's economic needs, the Development Commission's appeal to growth loses. That's the Wildlife Commission's side.$batch09$), ($batch09$C$batch09$, $batch09$Regulate only after commercial development has actually been found to reduce endangered species. The Development Commission says Figoria has conserved, and its development "might not affect wildlife." So no such harm has been found, and regulation isn't justified yet. The Wildlife Commission wants regulation before any harm, which this principle rules out.$batch09$), ($batch09$D$batch09$, $batch09$This is the trap, picked by 12%. It talks about how different nations have harmed the environment to different degrees. That's the Development Commission's theme, so it feels like their answer. But read what it concludes: regulation cannot allow for those differences. The commission's whole complaint is that Figoria's record of conserving should count. D says it doesn't.$batch09$), ($batch09$E$batch09$, $batch09$If further depletion is imprudent, developing the wetlands is imprudent. That supports the Wildlife Commission.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT118-S3-Q8$batch09$ AND e.id=$batch09$22045154-79ec-4a5a-a196-5b1030ef9c60$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
